"It's Saturday morning.":"Cumartesi sabahı.",
"I want to bake a cake for Mum!":"Anneme pasta yapmak istiyorum!",
"Can I help you?":"Sana yardım edebilir miyim?",
"Yes! We need flour, eggs and sugar.":"Evet! Un, yumurta ve şeker lazım.",
"Meow!":"Miyav!",
"Pus, don't eat the butter!":"Pus, tereyağını yeme!",
"Oh no! Flour all over the kitchen!":"Eyvah! Mutfağın her yeri un oldu!",
"The cake is ready. It's a bit crooked...":"Pasta hazır. Biraz eğri olmuş…",
"But it smells so good!":"Ama kokusu harika!",
"Thank you so much, my darlings! This is the best cake in the world!":"Çok teşekkür ederim canlarım! Bu dünyanın en güzel pastası!",
"Meow, meow!":"Miyav, miyav!",
"Good morning, Leo! Today is your first day at school.":"Günaydın Leo! Bugün okuldaki ilk günün.",
"I'm a little scared, Mum.":"Biraz korkuyorum anne.",
"Hi and welcome! My name is Ingrid. What's your name?":"Merhaba, hoş geldin! Benim adım Ingrid. Senin adın ne?",
"My name is Leo. I come from Ukraine.":"Benim adım Leo. Ukrayna'dan geliyorum.",
"Hi, Leo! Do you want to sit next to me?":"Merhaba Leo! Yanıma oturmak ister misin?",
"Yes, I'd love to!":"Evet, çok isterim!",
"What is one plus two?":"Bir artı iki kaç eder?",
"Three!":"Üç!",
"You're so clever!":"Çok akıllısın!",
"Break time!":"Teneffüs!",
"Come on, let's play football!":"Hadi, futbol oynayalım!",
"How was school?":"Okul nasıldı?",
"Super fun! Nora is my new friend!":"Çok eğlenceliydi! Nora yeni arkadaşım!",
"Today we're going for a walk in the forest!":"Bugün ormanda yürüyüşe çıkıyoruz!",
"Hooray! I'll bring the basket.":"Yaşasın! Sepeti ben alırım.",
"Look, there's a mushroom!":"Bak, orada bir mantar var!",
"That mushroom is poisonous. Don't eat it!":"O mantar zehirli. Sakın yeme!",
"There are lots of blueberries here!":"Burada bir sürü yaban mersini var!",
"Yum! They're so sweet!":"Mmm! Çok tatlılar!",
"What was that?":"O neydi?",
"A moose! It's huge!":"Bir sığın! Kocaman!",
"Then it starts to rain.":"Sonra yağmur başlıyor.",
"Be quiet. Now we walk home calmly.":"Sessiz ol. Şimdi sakince eve yürüyoruz.",
"Now we're going to drink hot cocoa.":"Şimdi sıcak kakao içeceğiz.",
"That was a lovely walk!":"Ne güzel bir yürüyüştü!",
"And we saw a real moose!":"Üstelik gerçek bir sığın gördük!",
"Mia, can you do the shopping for me?":"Mia, benim için alışveriş yapar mısın?",
"Yes! What do you need?":"Tabii! Ne lazım?",
"We need milk, bread and apples. Here are a hundred kroner.":"Süt, ekmek ve elma lazım. Al sana yüz kron.",
"Thanks, Mum!":"Sağ ol anne!",
"Excuse me, where is the milk?":"Affedersiniz, süt nerede?",
"The milk is over there, by the bread.":"Süt şurada, ekmeğin yanında.",
"I'll take six red apples.":"Altı tane kırmızı elma alayım.",
"That will be eighty kroner.":"Seksen kron tutuyor.",
"Here you go, here's a hundred.":"Buyurun, yüz kron.",
"Twenty kroner change. Have a nice day!":"Yirmi kron para üstü. İyi günler!",
"You're so clever, Mia! Thank you so much.":"Çok akıllısın Mia! Çok teşekkür ederim.",
"That was easy!":"Kolaydı!",
"Meow! Milk?":"Miyav! Süt?",
