"A New Friend at School":"Okulda Yeni Bir Arkadaş",
"Good morning! Welcome to our class.":"Günaydın! Sınıfımıza hoş geldin.",
"Hello! Thank you.":"Merhaba! Teşekkür ederim.",
"Hi! What is your name?":"Selam! Adın ne?",
"My name is Nora. What is your name?":"Benim adım Nora. Senin adın ne?",
"I am Leo. Nice to meet you!":"Ben Leo. Tanıştığımıza memnun oldum!",
"Nice to meet you too.":"Ben de tanıştığımıza memnun oldum.",
"How old are you?":"Kaç yaşındasın?",
"I am nine years old. And you?":"Dokuz yaşındayım. Sen?",
"I am ten. Where are you from, Humphrey?":"Ben on yaşındayım. Nerelisin, Humphrey?",
"I am from Kenya, but I live here now.":"Ben Kenya’lıyım, ama artık burada yaşıyorum.",
"Can we play together after school?":"Okuldan sonra birlikte oynayabilir miyiz?",
"Yes, of course! See you at three.":"Evet, tabii! Saat üçte görüşürüz.",
