"A Rainy Day in London":"Londra’da Yağmurlu Bir Gün",
"Oh no, it is raining again!":"Ah hayır, yine yağmur yağıyor!",
"Welcome to London. Did you bring an umbrella?":"Londra’ya hoş geldiniz. Şemsiyenizi getirdiniz mi?",
"Yes, but the wind is very strong.":"Evet, ama rüzgâr çok güçlü.",
"We cannot walk in the park today.":"Bugün parkta yürüyemeyiz.",
"Let us take the bus to the museum instead.":"Bunun yerine otobüsle müzeye gidelim.",
"Great idea! Which bus goes there?":"Harika fikir! Oraya hangi otobüs gidiyor?",
"Number twenty-four. It takes fifteen minutes.":"Yirmi dört numara. On beş dakika sürüyor.",
"Perfect. The museum is free on Sundays.":"Mükemmel. Müze pazar günleri ücretsiz.",
"Look at this old map of the city!":"Şehrin bu eski haritasına bak!",
"I love rainy days when we find something new.":"Yeni bir şey bulduğumuzda yağmurlu günleri severim.",
"In the evening the sun came out.":"Akşam güneş açtı.",
