"Lost in the City":"Şehirde Kaybolmak",
"Excuse me, could you help me? I think I am lost.":"Affedersiniz, bana yardım edebilir misiniz? Sanırım kayboldum.",
"Of course. Where do you want to go?":"Tabii. Nereye gitmek istiyorsunuz?",
"I am looking for the city library.":"Şehir kütüphanesini arıyorum.",
"Go straight on and turn left at the traffic lights.":"Dümdüz gidin ve trafik ışıklarında sola dönün.",
"Then walk past the bus stop. The library is opposite the bank.":"Sonra otobüs durağını geçin. Kütüphane bankanın karşısında.",
"Is it far from here?":"Buradan uzak mı?",
"No, it only takes about ten minutes on foot.":"Hayır, yürüyerek sadece yaklaşık on dakika sürer.",
"Great. And is there a café near the library?":"Harika. Peki kütüphanenin yakınında bir kafe var mı?",
"Later, Ruslan took the wrong bus.":"Sonra, Ruslan yanlış otobüse bindi.",
"This bus does not go there. Get off at the next stop and cross the road.":"Bu otobüs oraya gitmiyor. Bir sonraki durakta in ve yolu karşıdan karşıya geç.",
"Finally! The library is on the corner, just like you said.":"Nihayet! Kütüphane tam dediğin gibi köşede.",
"Well done! Now you will never get lost again.":"Aferin! Artık bir daha asla kaybolmayacaksın.",
