"Grammar in real life":"Gerçek hayatta dilbilgisi (Bir Norveççe harf, ses ya da sayı hakkında öğrenenler için açıklama)",
"What is coding?":"Kodlama nedir?",
"The school has a robot called Robo. He only follows exact commands, and the children learn that a program is commands in the right order.":"Okulda Robo adında bir robot var. Yalnızca tam komutları uygular ve çocuklar programın doğru sırada verilen komutlar olduğunu öğrenir.",
"Look, Nora! The school has got a robot.":"Bak Nora! Okula bir robot gelmiş.",
"Hi, robot! What is your name?":"Merhaba robot! Adın ne?",
"Hi! My name is Robo. I do what you tell me.":"Merhaba! Benim adım Robo. Bana ne söylerseniz onu yaparım.",
"Robo only understands commands. We call that programming.":"Robo yalnızca komutları anlar. Buna programlama diyoruz.",
"What is a command?":"Komut nedir?",
"A command is a short instruction, for example “walk” or “turn”.":"Komut kısa bir talimattır, örneğin “yürü” ya da “dön”.",
"Robo, take two steps forward!":"Robo, iki adım ileri git!",
"Walking. One, two. Done!":"Yürüyorum. Bir, iki. Bitti!",
"Robo, make me a pizza!":"Robo, bana pizza yap!",
"Error! I do not know the command “pizza”.":"Hata! “Pizza” komutunu bilmiyorum.",
"A program is many commands in the right order.":"Program, doğru sırada birçok komuttur.",
"So we have to think step by step!":"Yani adım adım düşünmeliyiz!",
"I want to learn to code!":"Kodlamayı öğrenmek istiyorum!",
"And I want to learn to make pizza.":"Ben de pizza yapmayı öğrenmek istiyorum.",
