"step by step":"adım adım",
"The sandwich algorithm":"Sandviç algoritması",
"Leo teaches Robo the robot to make a sandwich. Robo does everything literally, so Leo learns that an algorithm must be exact and in the right order.":"Leo, robot Robo’ya sandviç yapmayı öğretir. Robo her şeyi kelimesi kelimesine yapar; Leo da algoritmanın kesin ve doğru sırada olması gerektiğini öğrenir.",
"Dad, I am going to teach Robo to make a sandwich.":"Baba, Robo’ya sandviç yapmayı öğreteceğim.",
"Then you need an algorithm.":"O zaman bir algoritmaya ihtiyacın var.",
"What is an algorithm?":"Algoritma nedir?",
"An algorithm is like a recipe: step by step, in the right order.":"Algoritma bir tarif gibidir: adım adım, doğru sırada.",
"Step one: Take the bread. Step two: Put on butter.":"Birinci adım: Ekmeği al. İkinci adım: Tereyağı sür.",
"Butter on … the table? Done!":"Tereyağı … masaya mı? Tamam!",
"Ha ha! You have to say exactly what Robo should do.":"Ha ha! Robo’nun ne yapacağını tam olarak söylemelisin.",
"New step two: Put butter on the slice of bread!":"Yeni ikinci adım: Ekmek dilimine tereyağı sür!",
"Step three: Put on cheese. Step four: Give the sandwich to Leo.":"Üçüncü adım: Peynir koy. Dördüncü adım: Sandviçi Leo’ya ver.",
"Done! Here you are.":"Tamam! Buyurun.",
"Mmm! The algorithm works!":"Mmm! Algoritma çalışıyor!",
"And remember: the order is important. First butter, then cheese.":"Unutma: sıra önemlidir. Önce tereyağı, sonra peynir.",
"an algorithm":"algoritma",
"a slice of bread, a sandwich":"bir dilim ekmek, sandviç",
"a cheese":"peynir",
"to put on":"üstüne koymak",
"done, carried out":"yapıldı, tamamlandı",
"important":"önemli",
"then":"sonra",
"Repeat! Robo dances":"Tekrarla! Robo dans ediyor",
"Nora wants Robo to dance, but there are too many commands. The teacher shows a loop: “repeat 4 times” — and the program becomes short.":"Nora, Robo’nun dans etmesini istiyor ama çok fazla komut var. Öğretmen bir döngü gösteriyor: “4 kez tekrarla” — ve program kısalıyor.",
"Robo, jump! Clap! Jump! Clap! Jump! Clap!":"Robo, zıpla! Alkışla! Zıpla! Alkışla! Zıpla! Alkışla!",
"Jump. Clap. Jump. Clap …":"Zıpla. Alkışla. Zıpla. Alkışla …",
"Phew, that is a lot to write.":"Of, yazacak çok şey var.",
"Use a loop! A loop repeats commands.":"Döngü kullan! Döngü komutları tekrarlar.",
"Write: repeat four times: jump and clap.":"Yaz: dört kez tekrarla: zıpla ve alkışla.",
"So short!":"Ne kadar kısa!",
"Jump, clap! Jump, clap! Jump, clap! Jump, clap!":"Zıpla, alkışla! Zıpla, alkışla! Zıpla, alkışla! Zıpla, alkışla!",
"Robo is dancing!":"Robo dans ediyor!",
"Can we repeat it a hundred times?":"Yüz kez tekrarlayabilir miyiz?",
"Yes. Computers never get tired.":"Evet. Bilgisayarlar asla yorulmaz.",
"But Robo is getting dizzy …":"Ama Robo’nun başı dönüyor …",
"Ha ha! We are stopping the loop now.":"Ha ha! Şimdi döngüyü durduruyoruz.",
