"If it rains …":"Eğer yağmur yağarsa …",
"Robo does not know when to take an umbrella. Leo and Mum write him a rule: if it rains — an umbrella, otherwise — sunglasses.":"Robo ne zaman şemsiye alacağını bilmiyor. Leo ve annesi ona bir kural yazar: yağmur yağarsa şemsiye, yoksa güneş gözlüğü.",
"Robo, we are going out. Bring an umbrella.":"Robo, dışarı çıkıyoruz. Şemsiye al.",
"Why? The sun is shining.":"Neden? Güneş parlıyor.",
"You are right, Robo. We need a rule.":"Haklısın Robo. Bir kurala ihtiyacımız var.",
"If it rains, we take an umbrella.":"Yağmur yağarsa şemsiye alırız.",
"If it rains, then we take an umbrella. Otherwise we take sunglasses.":"Yağmur yağarsa şemsiye alırız. Yoksa güneş gözlüğü alırız.",
"If … then … otherwise. Understood!":"Eğer … ise … değilse. Anlaşıldı!",
"It is raining. I am taking the umbrella.":"Yağmur yağıyor. Şemsiyeyi alıyorum.",
"Good, Robo!":"Aferin Robo!",
"Now the sun is shining. I am taking sunglasses.":"Şimdi güneş parlıyor. Güneş gözlüğü alıyorum.",
"Robo thinks like a computer.":"Robo bir bilgisayar gibi düşünüyor.",
"If I tidy my room, then I get ice cream?":"Odamı toplarsam dondurma alır mıyım?",
"Yes! That is a good rule.":"Evet! Bu iyi bir kural.",
"otherwise, else":"aksi halde, değilse",
