"to think":"düşünmek",
"Points in the box":"Kutudaki puanlar",
"Nora and Leo make a game: a cat catches fish and gets points. The teacher explains a variable — a box with a name where the computer keeps a number.":"Nora ve Leo bir oyun yapıyor: bir kedi balık yakalayıp puan kazanıyor. Öğretmen değişkeni anlatıyor — bilgisayarın bir sayıyı sakladığı, adı olan bir kutu.",
"We are making a game! Every time the cat catches a fish, we get a point.":"Bir oyun yapıyoruz! Kedi her balık yakaladığında bir puan alıyoruz.",
"But where will the computer remember the points?":"Ama bilgisayar puanları nerede hatırlayacak?",
"In a variable. A variable is like a box with a name.":"Bir değişkende. Değişken, adı olan bir kutu gibidir.",
"The box is called “points”. Right now there is zero in the box.":"Kutunun adı “puan”. Şu anda kutuda sıfır var.",
"The cat catches a fish!":"Kedi bir balık yakaladı!",
"Then we write: points equals points plus one.":"O zaman şunu yazarız: puan eşittir puan artı bir.",
"Points is one. Points is two. Points is three!":"Puan bir. Puan iki. Puan üç!",
"The value in the box changes!":"Kutudaki değer değişiyor!",
"Can we have more boxes?":"Daha fazla kutumuz olabilir mi?",
"Yes. Name, lives and speed … A game has many variables.":"Evet. Ad, can ve hız … Bir oyunda birçok değişken vardır.",
"We have ten points! We won!":"On puanımız var! Kazandık!",
"The variable “joy” is now a hundred.":"“Neşe” değişkeni şimdi yüz.",
