"to keep, to take care of":"saklamak, bakmak",
"Find the bug!":"Hatayı bul!",
"Robo has to reach the star but walks into a wall. The children read the program line by line, find the bug and fix it.":"Robo yıldıza ulaşmalı ama duvara çarpıyor. Çocuklar programı satır satır okuyor, hatayı bulup düzeltiyor.",
"Robo has to walk to the star. I have written the program.":"Robo yıldıza yürümeli. Programı yazdım.",
"I am starting the program now.":"Programı şimdi başlatıyorum.",
"Ouch! I walked straight into the wall.":"Ay! Doğruca duvara yürüdüm.",
"Oops! The program has a bug.":"Hay aksi! Programda bir hata var.",
"We call an error in a program a bug.":"Programdaki hataya bug deriz.",
"Finding and fixing the error is called debugging.":"Hatayı bulup düzeltmeye hata ayıklama denir.",
"We read the program line by line: forward, forward, right …":"Programı satır satır okuyoruz: ileri, ileri, sağ …",
"There! It should say left, not right.":"İşte! Orada sağ değil, sol yazmalı.",
"Now I will fix the bug and try again.":"Şimdi hatayı düzeltip tekrar deneyeceğim.",
"I am at the star! The program works.":"Yıldızın yanındayım! Program çalışıyor.",
"All programmers make mistakes. The important thing is to try again.":"Bütün programcılar hata yapar. Önemli olan yeniden denemektir.",
"Mistakes are part of learning!":"Hatalar öğrenmenin bir parçasıdır!",
