"Which language?":"Hangi dil?",
"Leo asks Robo which language he speaks. The teacher explains programming languages: Scratch, Python, JavaScript, HTML and CSS, Swift, Kotlin and C#.":"Leo, Robo’ya hangi dili konuştuğunu soruyor. Öğretmen programlama dillerini anlatıyor: Scratch, Python, JavaScript, HTML ve CSS, Swift, Kotlin ve C#.",
"Robo, which language do you speak? Norwegian?":"Robo, hangi dili konuşuyorsun? Norveççe mi?",
"I understand programming languages. There are many!":"Programlama dillerini anlıyorum. Çok sayıda var!",
"Children often start with Scratch. There we move colourful blocks.":"Çocuklar genellikle Scratch ile başlar. Orada renkli blokları taşırız.",
"It looks like Lego!":"Lego’ya benziyor!",
"Python is easy to read. It is used for games, data and artificial intelligence.":"Python’u okumak kolaydır. Oyunlar, veri ve yapay zekâ için kullanılır.",
"Artificial intelligence? Like Robo?":"Yapay zekâ mı? Robo gibi mi?",
"HTML builds web pages, and CSS makes them pretty. JavaScript makes them move.":"HTML web sayfalarını kurar, CSS onları güzelleştirir. JavaScript ise hareket ettirir.",
"So the school website is made with them?":"Yani okulun web sitesi bunlarla mı yapıldı?",
"We make iPhone apps with Swift, and Android apps with Kotlin.":"iPhone uygulamalarını Swift ile, Android uygulamalarını Kotlin ile yaparız.",
"And games?":"Ya oyunlar?",
"Many games are made with C#.":"Birçok oyun C# ile yapılır.",
"Which language should I learn first?":"Önce hangi dili öğrenmeliyim?",
"Start with Scratch or Python. The most important thing is to think logically.":"Scratch ya da Python ile başla. En önemlisi mantıklı düşünmektir.",
