"A model of the school":"Okulun modeli",
"The class makes a model of the schoolyard. The children learn that a model is a simple copy, that things in a program have properties, and that you draw the plan before the code.":"Sınıf, okul bahçesinin bir modelini yapıyor. Çocuklar modelin basit bir kopya olduğunu, programdaki nesnelerin özellikleri olduğunu ve planın koddan önce çizildiğini öğreniyor.",
"Today we are making a model of the schoolyard.":"Bugün okul bahçesinin bir modelini yapıyoruz.",
"What is a model?":"Model nedir?",
"A model is a simple copy of something real. A map is a model too.":"Model, gerçek bir şeyin basit bir kopyasıdır. Harita da bir modeldir.",
"Like the map in a game!":"Oyundaki harita gibi!",
"We only draw the important things: the school, the gate and the football pitch.":"Sadece önemli şeyleri çiziyoruz: okulu, kapıyı ve futbol sahasını.",
"We do not need to draw every single leaf.":"Her bir yaprağı çizmemize gerek yok.",
"In a program we describe things with properties. A ball has a colour, a size and a speed.":"Bir programda nesneleri özellikleriyle tanımlarız. Bir topun rengi, boyutu ve hızı vardır.",
"So the ball is white and fast!":"Yani top beyaz ve hızlı!",
"And a flowchart shows what happens, step by step.":"Akış şeması da ne olduğunu adım adım gösterir.",
"First we draw the plan, then we write the code.":"Önce planı çizeriz, sonra kodu yazarız.",
"I have made a model of Leo: hungry, happy and likes football.":"Leo’nun bir modelini yaptım: aç, mutlu ve futbolu seviyor.",
