"A website for Pus: HTML basics":"Pus için bir web sitesi: HTML temelleri",
"Nora and Leo make a website about Pus the cat. Robo explains HTML: tags in angle brackets, a heading <h1>, a paragraph <p>, an image <img> and a link <a>.":"Nora ve Leo, kedi Pus hakkında bir web sitesi yapıyor. Robo HTML’i anlatıyor: köşeli parantezlerdeki etiketler, başlık <h1>, paragraf <p>, resim <img> ve bağlantı <a>.",
"I want to make a website about our cat, Pus!":"Kedimiz Pus hakkında bir web sitesi yapmak istiyorum!",
"Then we need HTML.":"O zaman HTML’e ihtiyacımız var.",
"HTML builds web pages. It is made of tags.":"HTML web sayfalarını kurar. Etiketlerden oluşur.",
"What is a tag?":"Etiket nedir?",
"A tag is a short word in angle brackets, for example p.":"Etiket, köşeli parantez içindeki kısa bir kelimedir, örneğin p.",
"Most tags have a start and an end. The end tag has a slash.":"Çoğu etiketin bir başı ve sonu vardır. Kapanış etiketinde eğik çizgi bulunur.",
"Like a sandwich!":"Sandviç gibi!",
"I write h1 and “Pus”. It becomes a big heading!":"h1 ve “Pus” yazıyorum. Büyük bir başlık oluyor!",
"Yes. h1 means heading number one.":"Evet. h1, bir numaralı başlık demektir.",
"With p we make a paragraph, and with img we show a picture.":"p ile paragraf yaparız, img ile resim gösteririz.",
"Look, a picture of Pus!":"Bak, Pus’un bir resmi!",
"Finally a link. The a tag takes us to another page.":"Son olarak bir bağlantı. a etiketi bizi başka bir sayfaya götürür.",
"The website is ready! Next time we will make it pretty with CSS.":"Web sitesi hazır! Bir dahaki sefere CSS ile güzelleştireceğiz.",
